class Solution { public: int oddEvenJumps(vector<int>& arr){int n=arr.size(),answer=1;vector<bool> odd(n),even(n);odd[n-1]=even[n-1]=true;map<int,int> positions{{arr[n-1],n-1}};for(int i=n-2;i>=0;--i){auto higher=positions.lower_bound(arr[i]);if(higher!=positions.end())odd[i]=even[higher->second];auto above=positions.upper_bound(arr[i]);if(above!=positions.begin()){--above;even[i]=odd[above->second];}if(odd[i])++answer;positions[arr[i]]=i;}return answer;} };
